@if(in_array($record->status,['queued','staging','validation_queued','validating','approval_queued','approving'],true))<script>(()=>{const u=@json(route('viva.mapping.status',$record));const f=v=>new Intl.NumberFormat().format(v??0);const poll=async()=>{try{const r=await fetch(u,{headers:{Accept:'application/json'}});if(!r.ok)return setTimeout(poll,3000);const d=await r.json();document.getElementById('batch-status').textContent=d.status.replaceAll('_',' ');document.getElementById('progress-label').textContent=Number(d.progress_percent).toFixed(2)+'%';document.getElementById('progress-bar').style.width=Math.min(100,Number(d.progress_percent))+'%';document.getElementById('processed-count').textContent=f(d.processed_rows);document.getElementById('total-count').textContent=f(d.total_rows);for(const k of ['total_rows','staged_rows','valid_rows','invalid_rows','identity_conflict_rows','approved_rows']){const e=document.getElementById('metric-'+k);if(e)e.textContent=f(d[k]);}if(d.finished)setTimeout(()=>location.reload(),700);else setTimeout(poll,1500);}catch(e){setTimeout(poll,4000)}};setTimeout(poll,800)})();</script>@endif
